using System.Collections;
using UnityEngine;

public class CameraFollow : MonoBehaviour
{
    [Tooltip("따라갈 대상. 비워두면 씬의 Player를 자동으로 찾음")]
    public Transform target;

    [Range(1f, 30f)]
    public float smoothSpeed = 15f;

    private float zOffset;
    private Camera cam;

    IEnumerator Start()
    {
        zOffset = transform.position.z;
        cam = GetComponent<Camera>();

        // MapGenerator.Start()가 먼저 끝나도록 한 프레임 대기
        yield return null;

        if (target == null)
        {
            Player p = FindFirstObjectByType<Player>();
            if (p != null) target = p.transform;
        }

        // 처음엔 즉시 스냅 (부드럽게 이동하지 않고 바로 붙음)
        if (target != null)
            transform.position = new Vector3(target.position.x, target.position.y, zOffset);
    }

    void LateUpdate()
    {
        if (target == null) return;

        Vector3 goal = new(target.position.x, target.position.y, zOffset);
        Vector3 pos  = Vector3.Lerp(transform.position, goal, smoothSpeed * Time.deltaTime);

        // 카메라가 그리드 밖(빈 공간)을 보이지 않도록 클램프
        if (cam != null && cam.orthographic && GridManager.Instance != null)
        {
            float halfH = cam.orthographicSize;
            float halfW = halfH * cam.aspect;
            GridManager gm = GridManager.Instance;

            pos.x = Mathf.Clamp(pos.x, halfW,            gm.width  - 1 - halfW);
            pos.y = Mathf.Clamp(pos.y, halfH, gm.height - 1 - halfH);
        }

        transform.position = pos;
    }
}

