using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Tilemaps;

public class GridManager : MonoBehaviour
{
    public static GridManager Instance;

    [Header("Grid Size")]
    public int width  = 40;
    public int height = 40;

    [Header("Tilemaps (인스펙터에서 연결)")]
    public Tilemap floorTilemap;
    public Tilemap wallTilemap;
    public TileBase floorTile;
    public TileBase wallTile;

    private bool[,] wallGrid;
    private readonly Dictionary<Vector2Int, Unit> unitMap = new();

    void Awake()
    {
        Instance  = this;
        wallGrid  = new bool[width, height];
    }

    // ─── 범위 ────────────────────────────────────────────────
    public bool IsInsideGrid(Vector2Int pos)
        => pos.x >= 0 && pos.x < width && pos.y >= 0 && pos.y < height;

    // ─── 벽 ─────────────────────────────────────────────────
    public bool IsWall(Vector2Int pos)
        => !IsInsideGrid(pos) || wallGrid[pos.x, pos.y];

    public void SetWall(Vector2Int pos, bool isWall)
    {
        if (!IsInsideGrid(pos)) return;
        wallGrid[pos.x, pos.y] = isWall;

        if (floorTilemap == null || wallTilemap == null) return;

        Vector3Int tp = new(pos.x, pos.y, 0);
        if (isWall)
        {
            wallTilemap.SetTile(tp, wallTile);
            floorTilemap.SetTile(tp, null);
        }
        else
        {
            floorTilemap.SetTile(tp, floorTile);
            wallTilemap.SetTile(tp, null);
        }
    }

    // ─── 유닛 점유 ───────────────────────────────────────────
    public bool IsOccupied(Vector2Int pos)
        => unitMap.ContainsKey(pos);

    public bool IsBlocked(Vector2Int pos)
        => IsWall(pos) || IsOccupied(pos);

    public void RegisterUnit(Vector2Int pos, Unit unit)
        => unitMap[pos] = unit;

    public void UnregisterUnit(Vector2Int pos)
        => unitMap.Remove(pos);

    public Unit GetUnitAt(Vector2Int pos)
    {
        unitMap.TryGetValue(pos, out Unit unit);
        return unit;
    }

    // ─── 좌표 변환 ───────────────────────────────────────────
    public Vector3 GridToWorld(Vector2Int pos)
        => new(pos.x, pos.y, 0f);
}

