using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// ASCII 텍스트 파일을 파싱해 맵 데이터를 반환하는 유틸리티
///
/// 기호 규칙:
///   #  = 벽
///   .  = 바닥
///   P  = 플레이어 시작 위치 (바닥으로 처리)
///   1  = Mob1 스폰 위치  (바닥으로 처리)
/// </summary>
public static class MapLoader
{
    public struct MapData
    {
        public bool[,]          walls;
        public int              width, height;
        public Vector2Int       playerSpawn;
        public List<Vector2Int> mob1Spawns;
    }

    public static MapData Parse(TextAsset asset)
    {
        // 줄 분리 + Windows CRLF 제거
        string[] lines = asset.text.Split('\n');
        for (int i = 0; i < lines.Length; i++)
            lines[i] = lines[i].TrimEnd('\r');

        // 끝의 빈 줄 제거
        int validLines = lines.Length;
        while (validLines > 0 && string.IsNullOrWhiteSpace(lines[validLines - 1]))
            validLines--;

        int height = validLines;
        int width  = 0;
        for (int i = 0; i < validLines; i++)
            if (lines[i].Length > width) width = lines[i].Length;

        MapData data = new()
        {
            walls        = new bool[width, height],
            width        = width,
            height       = height,
            playerSpawn  = new Vector2Int(1, 1),
            mob1Spawns   = new List<Vector2Int>()
        };

        // 텍스트는 위→아래, 그리드 Y는 아래→위이므로 뒤집어서 읽음
        for (int row = 0; row < height; row++)
        {
            int   gridY = height - 1 - row;
            string line = row < lines.Length ? lines[row] : "";

            for (int col = 0; col < width; col++)
            {
                char c = col < line.Length ? line[col] : '#';

                switch (c)
                {
                    case '#':
                        data.walls[col, gridY] = true;
                        break;
                    case '.':
                        data.walls[col, gridY] = false;
                        break;
                    case 'P':
                        data.walls[col, gridY] = false;
                        data.playerSpawn = new Vector2Int(col, gridY);
                        break;
                    case '1':
                        data.walls[col, gridY] = false;
                        data.mob1Spawns.Add(new Vector2Int(col, gridY));
                        break;
                }
            }
        }

        return data;
    }
}

