using System.Collections.Generic;
using UnityEngine;

public class MapGenerator : MonoBehaviour
{
    // ─── 커스텀 맵 설정 ──────────────────────────────────────
    [Header("Custom Maps")]
    [Tooltip("인스펙터에서 층별 .txt 파일을 드래그. index 0 = 1층, index 1 = 2층 ...")]
    public TextAsset[] floorMaps;

    public int currentFloor = 1;

    // ─── 프로시저럴 맵 설정 (커스텀 맵 없을 때 사용) ────────
    [Header("Procedural Room Settings")]
    public int roomCount   = 8;
    public int minRoomSize = 4;
    public int maxRoomSize = 10;

    [Header("Player")]
    public Player playerPrefab;

    [Header("Tile Colors (Tilemap 없을 때 사용)")]
    public Color floorColor = new(0.35f, 0.35f, 0.35f);
    public Color wallColor  = new(0.12f, 0.12f, 0.12f);

    // ─── 내부 상태 ───────────────────────────────────────────
    private readonly List<RectInt>  rooms           = new();
    private          Vector2Int     customPlayerSpawn;
    private          List<Vector2Int> customMob1Spawns = new();
    private          bool           usingCustomMap  = false;

    // ─── 초기화 ──────────────────────────────────────────────

    void Start()
    {
        GenerateMap();
        RenderTiles();
        SpawnPlayer();
        SpawnMonsters();
    }

    // ─── 맵 생성 진입점 ──────────────────────────────────────

    void GenerateMap()
    {
        int idx = currentFloor - 1;
        if (floorMaps != null && idx >= 0 && idx < floorMaps.Length && floorMaps[idx] != null)
        {
            LoadCustomMap(floorMaps[idx]);
            return;
        }
        GenerateProceduralMap();
    }

    // ─── 커스텀 맵 로드 ──────────────────────────────────────

    void LoadCustomMap(TextAsset asset)
    {
        MapLoader.MapData data = MapLoader.Parse(asset);

        GridManager gm = GridManager.Instance;
        gm.Reinitialize(data.width, data.height);

        for (int x = 0; x < data.width; x++)
            for (int y = 0; y < data.height; y++)
                gm.SetWall(new Vector2Int(x, y), data.walls[x, y]);

        customPlayerSpawn = data.playerSpawn;
        customMob1Spawns  = data.mob1Spawns;
        usingCustomMap    = true;
    }

    // ─── 프로시저럴 맵 생성 ──────────────────────────────────

    void GenerateProceduralMap()
    {
        usingCustomMap = false;
        rooms.Clear();

        GridManager gm = GridManager.Instance;

        for (int x = 0; x < gm.width; x++)
            for (int y = 0; y < gm.height; y++)
                gm.SetWall(new Vector2Int(x, y), true);

        int attempts = 0;
        while (rooms.Count < roomCount && attempts < 200)
        {
            attempts++;

            int w = Random.Range(minRoomSize, maxRoomSize + 1);
            int h = Random.Range(minRoomSize, maxRoomSize + 1);
            int x = Random.Range(1, gm.width  - w - 1);
            int y = Random.Range(1, gm.height - h - 1);

            RectInt candidate = new(x, y, w, h);
            if (!OverlapsExisting(candidate))
            {
                CarveRoom(candidate);
                rooms.Add(candidate);
            }
        }

        for (int i = 1; i < rooms.Count; i++)
            CarveCorridorL(Center(rooms[i - 1]), Center(rooms[i]));
    }

    bool OverlapsExisting(RectInt candidate)
    {
        foreach (RectInt r in rooms)
        {
            RectInt expanded = new(r.x - 1, r.y - 1, r.width + 2, r.height + 2);
            if (expanded.Overlaps(candidate)) return true;
        }
        return false;
    }

    void CarveRoom(RectInt room)
    {
        for (int x = room.x; x < room.xMax; x++)
            for (int y = room.y; y < room.yMax; y++)
                GridManager.Instance.SetWall(new Vector2Int(x, y), false);
    }

    void CarveCorridorL(Vector2Int a, Vector2Int b)
    {
        int x = a.x;
        while (x != b.x)
        {
            GridManager.Instance.SetWall(new Vector2Int(x, a.y), false);
            x += x < b.x ? 1 : -1;
        }

        int y = a.y;
        while (y != b.y)
        {
            GridManager.Instance.SetWall(new Vector2Int(b.x, y), false);
            y += y < b.y ? 1 : -1;
        }
    }

    // ─── 타일 렌더링 ─────────────────────────────────────────

    void RenderTiles()
    {
        GridManager gm = GridManager.Instance;
        if (gm.floorTilemap != null) return;

        Sprite floorSpr = MakeSprite(floorColor);
        Sprite wallSpr  = MakeSprite(wallColor);

        Transform root = new GameObject("Map").transform;

        for (int x = 0; x < gm.width; x++)
        {
            for (int y = 0; y < gm.height; y++)
            {
                bool isWall = gm.IsWall(new Vector2Int(x, y));

                GameObject tile = new(isWall ? "W" : "F");
                tile.transform.SetParent(root);
                tile.transform.position = gm.GridToWorld(new Vector2Int(x, y));

                SpriteRenderer sr = tile.AddComponent<SpriteRenderer>();
                sr.sprite       = isWall ? wallSpr : floorSpr;
                sr.sortingOrder = -1;
            }
        }
    }

    static Sprite MakeSprite(Color color)
    {
        Texture2D tex = new(1, 1);
        tex.SetPixel(0, 0, color);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, 1, 1), Vector2.one * 0.5f, 1f);
    }

    // ─── 플레이어 스폰 ────────────────────────────────────────

    void SpawnPlayer()
    {
        Vector2Int startPos = usingCustomMap
            ? customPlayerSpawn
            : (rooms.Count > 0 ? Center(rooms[0]) : new Vector2Int(1, 1));

        Player player = playerPrefab != null
            ? Instantiate(playerPrefab)
            : FindFirstObjectByType<Player>();

        if (player != null)
            player.Init(startPos);
    }

    // ─── 몬스터 스폰 ─────────────────────────────────────────

    void SpawnMonsters()
    {
        if (usingCustomMap)
        {
            foreach (Vector2Int pos in customMob1Spawns)
                SpawnMob(pos);
            return;
        }

        if (rooms.Count < 2) return;
        SpawnMob(Center(rooms[1]));
    }

    void SpawnMob(Vector2Int pos)
    {
        GameObject go = new("Mob1");

        SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
        sr.sprite       = MakeSprite(new Color(0.85f, 0.2f, 0.2f));
        sr.sortingOrder = 0;

        Mob1 mob = go.AddComponent<Mob1>();
        mob.Init(pos);
    }

    // ─── 유틸 ────────────────────────────────────────────────

    Vector2Int Center(RectInt room)
        => new(room.x + room.width / 2, room.y + room.height / 2);

    public Vector2Int GetRandomFloorPos()
    {
        if (rooms.Count == 0) return Vector2Int.zero;

        RectInt room = rooms[Random.Range(0, rooms.Count)];
        return new(
            Random.Range(room.x, room.xMax),
            Random.Range(room.y, room.yMax)
        );
    }
}

