using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// ASCII 텍스트 파일을 파싱해 맵 데이터를 반환하는 유틸리티
///
/// 기호 규칙:
///   #  = 벽
///   .  = 바닥
///   P  = 플레이어 시작 위치 (바닥으로 처리)
///   1  = Mob1 스폰 위치  (바닥으로 처리)
/// </summary>
public static class MapLoader
{
