///   D        = 차원비석 위치
/// </summary>
public static class MapLoader
{
    public struct MapData
    {
        public bool[,] walls;
        public int     width, height;

        // P 타일 전체 목록 (입장 시 랜덤 선택)
        public List<Vector2Int> playerSpawnZone;

        // 숫자 기호: 정확한 스폰 위치
        public List<Vector2Int> mob1ExactSpawns;   // '1'

        // 소문자 기호: 스폰 구역 ('a' → Mob1, 'b' → 미래 몬스터 등)
        public Dictionary<char, List<Vector2Int>> monsterSpawnZones;

        // 차원비석 위치
        public List<Vector2Int> dimensionStones;   // 'D'
    }

    public static MapData Parse(TextAsset asset)
    {
        string[] lines = asset.text.Split('\n');
        for (int i = 0; i < lines.Length; i++)
            lines[i] = lines[i].TrimEnd('\r');

        int validLines = lines.Length;
        while (validLines > 0 && string.IsNullOrWhiteSpace(lines[validLines - 1]))
            validLines--;

        int height = validLines;
        int width  = 0;
        for (int i = 0; i < validLines; i++)
            if (lines[i].Length > width) width = lines[i].Length;

        MapData data = new()
        {
            walls               = new bool[width, height],
            width               = width,
            height              = height,
            playerSpawnZone     = new List<Vector2Int>(),
            mob1ExactSpawns     = new List<Vector2Int>(),
            monsterSpawnZones   = new Dictionary<char, List<Vector2Int>>(),
            dimensionStones     = new List<Vector2Int>()
        };

        // 텍스트는 위→아래, 그리드 Y는 아래→위이므로 뒤집어서 읽음
        for (int row = 0; row < height; row++)
        {
            int    gridY = height - 1 - row;
            string line  = row < lines.Length ? lines[row] : "";

            for (int col = 0; col < width; col++)
            {
                char c = col < line.Length ? line[col] : '#';
                Vector2Int pos = new(col, gridY);

                switch (c)
                {
                    case '#':
                        data.walls[col, gridY] = true;
                        break;

                    case '.':
                        data.walls[col, gridY] = false;
                        break;

                    case 'P':
                        data.walls[col, gridY] = false;
                        data.playerSpawnZone.Add(pos);
                        break;

                    case '1':
                        data.walls[col, gridY] = false;
                        data.mob1ExactSpawns.Add(pos);
                        break;

                    case 'D':
                        data.walls[col, gridY] = false;
                        data.dimensionStones.Add(pos);
                        break;

                    default:
                        // 소문자 a~z → 몬스터 스폰 구역
                        if (c >= 'a' && c <= 'z')
                        {
                            data.walls[col, gridY] = false;
                            if (!data.monsterSpawnZones.ContainsKey(c))
                                data.monsterSpawnZones[c] = new List<Vector2Int>();
                            data.monsterSpawnZones[c].Add(pos);
                        }
                        break;
                }
            }
        }

        return data;
    }
}

