using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 프로젝트 창에서 우클릭 → Create → DAS → Monster Database 로 생성
/// 생성 후 Inspector에서 몬스터 목록 편집
/// </summary>
[CreateAssetMenu(fileName = "MonsterDatabase", menuName = "DAS/Monster Database")]
public class MonsterDatabase : ScriptableObject
{
    [System.Serializable]
    public class Entry
    {
        [Tooltip("맵 파일에서 이 몬스터를 나타내는 소문자 (a~z)")]
        public char   zoneChar   = 'a';

        [Tooltip("몬스터 이름 (Hierarchy에 표시됨)")]
        public string monsterName = "Monster";

        [Tooltip("최대 HP")]
        public int    maxHp      = 10;

        [Tooltip("공격력")]
        public int    attack     = 3;

        [Tooltip("스프라이트 색상")]
        public Color  color      = new(0.85f, 0.2f, 0.2f);

        [Tooltip("스폰 구역(a~z)당 스폰할 마리 수")]
        public int    spawnCount = 1;
    }

    public List<Entry> monsters = new();

    /// <summary>맵 기호로 항목 검색. 없으면 null 반환.</summary>
    public Entry Get(char zoneChar)
    {
        foreach (Entry e in monsters)
            if (e.zoneChar == zoneChar) return e;
        return null;
    }

    /// <summary>첫 번째 항목 반환 (맵의 '1' 기호용 폴백).</summary>
    public Entry GetFirst()
        => monsters.Count > 0 ? monsters[0] : null;
}

