using UnityEngine;

/// <summary>
/// 데이터베이스에서 설정값을 읽는 범용 몬스터.
/// 현재 AI: 플레이어를 향해 거리가 큰 축 우선으로 이동.
/// </summary>
public class GenericMonster : Monster
{
    public MonsterDatabase.Entry Data { get; set; }

    public override void TakeTurn()
    {
        if (player == null) return;

        Vector2Int toPlayer = player.GridPosition - GridPosition;
        if (toPlayer == Vector2Int.zero) return;

        Vector2Int primary, secondary;

        if (Mathf.Abs(toPlayer.x) >= Mathf.Abs(toPlayer.y))
        {
            primary   = new Vector2Int(toPlayer.x > 0 ? 1 : -1, 0);
            secondary = toPlayer.y != 0
                ? new Vector2Int(0, toPlayer.y > 0 ? 1 : -1)
                : Vector2Int.zero;
        }
        else
        {
            primary   = new Vector2Int(0, toPlayer.y > 0 ? 1 : -1);
            secondary = toPlayer.x != 0
                ? new Vector2Int(toPlayer.x > 0 ? 1 : -1, 0)
                : Vector2Int.zero;
        }

        if (!TryMove(primary) && secondary != Vector2Int.zero)
            TryMove(secondary);
    }
}

