                tile.transform.position = gm.GridToWorld(new Vector2Int(x, y));

                SpriteRenderer sr = tile.AddComponent<SpriteRenderer>();
                sr.sprite       = isWall ? wallSpr : floorSpr;
                sr.sortingOrder = -1;
            }
        }
    }

    public static Sprite MakeSprite(Color color)
    {
        Texture2D tex = new(1, 1);
        tex.SetPixel(0, 0, color);
        tex.Apply();
        return Sprite.Create(tex, new Rect(0, 0, 1, 1), Vector2.one * 0.5f, 1f);
    }

    // ─── 플레이어 스폰 ────────────────────────────────────────

    void SpawnPlayer()
    {
        Vector2Int startPos = usingCustomMap
            ? customPlayerSpawn
            : (rooms.Count > 0 ? Center(rooms[0]) : new Vector2Int(1, 1));

        Player player = playerPrefab != null
            ? Instantiate(playerPrefab)
            : FindFirstObjectByType<Player>();

        if (player != null)
            player.Init(startPos);
    }

    // ─── 몬스터 스폰 ─────────────────────────────────────────

    void SpawnMonsters()
    {
        if (usingCustomMap)
        {
            // '1' 기호: DB 첫 번째 항목을 정확한 위치에 스폰
            foreach (Vector2Int pos in customExactSpawns)
                SpawnMonster(pos, monsterDatabase != null ? monsterDatabase.GetFirst() : null);

            // 'a'~'z' 기호: DB에서 zoneChar 검색 후 spawnCount만큼 스폰
            foreach (KeyValuePair<char, List<Vector2Int>> zone in customMonsterZones)
            {
                List<Vector2Int> positions = zone.Value;
                if (positions.Count == 0) continue;

                MonsterDatabase.Entry entry = monsterDatabase != null
                    ? monsterDatabase.Get(zone.Key)
                    : null;

                if (entry == null)
                {
                    Debug.LogWarning($"[MapGenerator] MonsterDatabase에 '{zone.Key}' 항목 없음");
                    continue;
                }

                int count = Mathf.Max(1, entry.spawnCount);
                for (int i = 0; i < count; i++)
                    SpawnMonster(positions[Random.Range(0, positions.Count)], entry);
            }
            return;
        }

        // 프로시저럴: rooms[1] 중앙에 DB 첫 번째 몬스터
        if (rooms.Count < 2) return;
        SpawnMonster(Center(rooms[1]), monsterDatabase != null ? monsterDatabase.GetFirst() : null);
    }

    void SpawnMonster(Vector2Int pos, MonsterDatabase.Entry entry)
    {
        Color  color = entry != null ? entry.color       : new Color(0.85f, 0.2f, 0.2f);
        string name  = entry != null ? entry.monsterName : "Monster";

        GameObject go = new(name);

        SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
        sr.sprite       = MakeSprite(color);
        sr.sortingOrder = 0;

        GenericMonster monster = go.AddComponent<GenericMonster>();
        monster.Data = entry;
        monster.Init(pos);
    }

    // ─── 차원비석 스폰 ────────────────────────────────────────

    void SpawnDimensionStones()
    {
        if (!usingCustomMap) return;

        foreach (Vector2Int pos in customDimStones)
        {
            GameObject go = new("DimensionStone");

            SpriteRenderer sr = go.AddComponent<SpriteRenderer>();
            sr.sprite       = MakeSprite(dimensionStoneColor);
            sr.sortingOrder = 0;

            DimensionStone ds = go.AddComponent<DimensionStone>();
            ds.Init(pos);
        }
    }

    // ─── 유틸 ────────────────────────────────────────────────

    Vector2Int Center(RectInt room)
        => new(room.x + room.width / 2, room.y + room.height / 2);

    public Vector2Int GetRandomFloorPos()
    {
        if (rooms.Count == 0) return Vector2Int.zero;

        RectInt room = rooms[Random.Range(0, rooms.Count)];
        return new(
            Random.Range(room.x, room.xMax),
            Random.Range(room.y, room.yMax)
        );
    }
}

